kernels.wgsl:
@group(0) @binding(0) var<storage, read> b0: array<f32>;
@group(0) @binding(1) var<storage, read> b1: array<f32>;
@group(0) @binding(2) var<storage, read> b2: array<f32>;
@group(0) @binding(3) var<storage, read> b3: array<f32>;
@group(0) @binding(4) var<storage, read_write> bout: array<f32>;

@compute @workgroup_size(64)
fn main(@builtin(local_invocation_index) lid: u32, @builtin(workgroup_id) wid: vec3<u32>, @builtin(num_workgroups) nwg: vec3<u32>) {
    let tid: i32 = i32(lid);
    let bid: i32 = i32(wid.x) + i32(wid.y) * i32(nwg.x);
    if (bid >= 6144i) { return; }
    var v_in0: f32 = 0.0;
    var v_in1: f32 = 0.0;
    var v_in2: f32 = 0.0;
    var v_v0: f32 = 0.0;
    var v_v1: f32 = 0.0;
    var v_v2: f32 = 0.0;
    var v_in3: f32 = 0.0;
    var v_v3: f32 = 0.0;
    var n_e: i32 = 0i;
    n_e = ((64i * bid) + tid);
    if (n_e < 393216i) {
        v_in0 = b1[((((12i * ((n_e / 12i) % 16i)) + (192i * ((n_e / 192i) % 256i))) + (n_e % 12i)) + (49152i * (n_e / 49152i)))];
        v_in1 = b2[((((12i * ((n_e / 12i) % 16i)) + (192i * ((n_e / 192i) % 256i))) + (n_e % 12i)) + (49152i * (n_e / 49152i)))];
        v_in2 = b3[((((12i * ((n_e / 12i) % 16i)) + (192i * ((n_e / 192i) % 256i))) + (n_e % 12i)) + (49152i * (n_e / 49152i)))];
        v_v0 = (v_in1 + v_in2);
        v_v1 = max(v_v0, 0.0);
        v_v2 = (v_in0 + v_v1);
        v_in3 = b0[((((12i * ((n_e / 12i) % 16i)) + (192i * ((n_e / 192i) % 256i))) + (n_e % 12i)) + (49152i * (n_e / 49152i)))];
        v_v3 = (v_v2 + v_in3);
        bout[((((12i * ((n_e / 12i) % 16i)) + (192i * ((n_e / 192i) % 256i))) + (n_e % 12i)) + (49152i * (n_e / 49152i)))] = v_v3;
    }
}
